SET local check_function_bodies = off;

CREATE EXTENSION "postgis" SCHEMA "extensions";

CREATE TABLE "public"."moderation_review" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "reviewer_id"         bigint                   NOT NULL,
  "submission_id"       bigint,
  "submission_revision" integer,
  "plant_edit_id"       bigint,
  "decision"            text                     NOT NULL,
  "comment"             text,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "moderation_review_comment_check" CHECK (((decision <> 'request_changes'::text) OR (NULLIF(btrim(comment), ''::text) IS NOT NULL))),
  CONSTRAINT "moderation_review_decision_check" CHECK ((decision = ANY (ARRAY['approve'::text, 'request_changes'::text, 'reject'::text]))),
  CONSTRAINT "moderation_review_one_target_check" CHECK (((submission_id IS NOT NULL) <> (plant_edit_id IS NOT NULL))),
  CONSTRAINT "moderation_review_pkey" PRIMARY KEY (id),
  CONSTRAINT "moderation_review_revision_check" CHECK ((((submission_id IS NULL) AND (submission_revision IS NULL)) OR ((submission_id IS NOT NULL) AND (submission_revision IS
    NOT NULL) AND (submission_revision >= 1))))
);

ALTER TABLE "public"."moderation_review"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."plant_edits" (
  "id"               bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "plant_id"         bigint                   NOT NULL,
  "user_id"          bigint                   NOT NULL,
  "proposed_changes" jsonb                    NOT NULL,
  "reason"           text                     NOT NULL DEFAULT ''::text,
  "status"           text                     NOT NULL DEFAULT 'pending'::text,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "plant_edits_pkey" PRIMARY KEY (id),
  CONSTRAINT "plant_edits_proposed_changes_check" CHECK ((jsonb_typeof(proposed_changes) = 'object'::text)),
  CONSTRAINT "plant_edits_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'changes_requested'::text, 'rejected'::text])))
);

ALTER TABLE "public"."plant_edits"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."plants" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "common_name"        text                     NOT NULL,
  "scientific_name"    text                     NOT NULL DEFAULT ''::text,
  "description"        text                     NOT NULL DEFAULT ''::text,
  "status"             text                     NOT NULL DEFAULT 'pending'::text,
  "created_by_id"      bigint,
  "best_submission_id" bigint,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"         timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "plants_pkey" PRIMARY KEY (id),
  CONSTRAINT "plants_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text])))
);

ALTER TABLE "public"."plants"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."reputation_events" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    bigint                   NOT NULL,
  "delta"      integer                  NOT NULL,
  "reason"     text                     NOT NULL,
  "review_id"  bigint,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "reputation_events_pkey" PRIMARY KEY (id),
  CONSTRAINT "reputation_events_reason_check"
    CHECK
    ((reason = ANY (ARRAY['submission_approved'::text, 'submission_rejected'::text, 'edit_approved'::text, 'edit_rejected'::text, 'review_completed'::text,
    'admin_adjustment'::text]))),
  CONSTRAINT "reputation_events_review_check" CHECK (((reason = 'admin_adjustment'::text) = (review_id IS NULL)))
);

ALTER TABLE "public"."reputation_events"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."submissions" (
  "id"          bigint                          GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"     bigint                          NOT NULL,
  "plant_id"    bigint                          NOT NULL,
  "location"    extensions.geometry(Point,4326) NOT NULL,
  "bloom_start" date                            NOT NULL,
  "bloom_end"   date                            NOT NULL,
  "description" text                            NOT NULL DEFAULT ''::text,
  "photo_key"   text                            NOT NULL,
  "status"      text                            NOT NULL DEFAULT 'pending'::text,
  "revision"    integer                         NOT NULL DEFAULT 1,
  "created_at"  timestamp with time zone        NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone        NOT NULL DEFAULT now(),
  CONSTRAINT "submissions_bloom_dates_check" CHECK ((bloom_end >= bloom_start)),
  CONSTRAINT "submissions_pkey" PRIMARY KEY (id),
  CONSTRAINT "submissions_revision_check" CHECK ((revision >= 1)),
  CONSTRAINT "submissions_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'changes_requested'::text, 'rejected'::text])))
);

ALTER TABLE "public"."submissions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."users" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email"        character varying(254)   NOT NULL,
  "password"     character varying(128)   NOT NULL,
  "display_name" text                     NOT NULL,
  "reputation"   integer                  NOT NULL DEFAULT 0,
  "role"         text                     NOT NULL DEFAULT 'user'::text,
  "is_active"    boolean                  NOT NULL DEFAULT true,
  "is_staff"     boolean                  NOT NULL DEFAULT false,
  "is_superuser" boolean                  NOT NULL DEFAULT false,
  "date_joined"  timestamp with time zone NOT NULL DEFAULT now(),
  "last_login"   timestamp with time zone,
  CONSTRAINT "users_email_key" UNIQUE (email),
  CONSTRAINT "users_pkey" PRIMARY KEY (id),
  CONSTRAINT "users_role_check" CHECK ((role = ANY (ARRAY['user'::text, 'moderator'::text, 'admin'::text])))
);

ALTER TABLE "public"."users"
  ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.set_updated_at()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$;

ALTER TABLE "public"."moderation_review"
  ADD CONSTRAINT "moderation_review_plant_edit_id_fkey" FOREIGN KEY (plant_edit_id) REFERENCES public.plant_edits(id);

ALTER TABLE "public"."plant_edits"
  ADD CONSTRAINT "plant_edits_plant_id_fkey" FOREIGN KEY (plant_id) REFERENCES public.plants(id);

ALTER TABLE "public"."reputation_events"
  ADD CONSTRAINT "reputation_events_review_id_fkey" FOREIGN KEY (review_id) REFERENCES public.moderation_review(id);

ALTER TABLE "public"."moderation_review"
  ADD CONSTRAINT "moderation_review_submission_id_fkey" FOREIGN KEY (submission_id) REFERENCES public.submissions(id);

ALTER TABLE "public"."plants"
  ADD CONSTRAINT "plants_best_submission_fk" FOREIGN KEY (best_submission_id) REFERENCES public.submissions(id) ON DELETE SET NULL;

ALTER TABLE "public"."submissions"
  ADD CONSTRAINT "submissions_plant_id_fkey" FOREIGN KEY (plant_id) REFERENCES public.plants(id);

ALTER TABLE "public"."moderation_review"
  ADD CONSTRAINT "moderation_review_reviewer_id_fkey" FOREIGN KEY (reviewer_id) REFERENCES public.users(id);

ALTER TABLE "public"."plant_edits"
  ADD CONSTRAINT "plant_edits_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.users(id);

ALTER TABLE "public"."plants"
  ADD CONSTRAINT "plants_created_by_id_fkey" FOREIGN KEY (created_by_id) REFERENCES public.users(id) ON DELETE SET NULL;

ALTER TABLE "public"."reputation_events"
  ADD CONSTRAINT "reputation_events_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.users(id);

ALTER TABLE "public"."submissions"
  ADD CONSTRAINT "submissions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.users(id);

CREATE INDEX moderation_review_plant_edit_id_idx ON public.moderation_review USING btree (plant_edit_id);

CREATE INDEX moderation_review_reviewer_id_idx ON public.moderation_review USING btree (reviewer_id);

CREATE INDEX moderation_review_submission_id_idx ON public.moderation_review USING btree (submission_id);

CREATE INDEX plant_edits_plant_id_idx ON public.plant_edits USING btree (plant_id);

CREATE INDEX plant_edits_status_idx ON public.plant_edits USING btree (status);

CREATE INDEX plant_edits_user_id_idx ON public.plant_edits USING btree (user_id);

CREATE INDEX plants_best_submission_id_idx ON public.plants USING btree (best_submission_id);

CREATE INDEX plants_created_by_id_idx ON public.plants USING btree (created_by_id);

CREATE INDEX reputation_events_review_id_idx ON public.reputation_events USING btree (review_id);

CREATE INDEX reputation_events_user_id_idx ON public.reputation_events USING btree (user_id);

CREATE INDEX submissions_location_idx ON public.submissions USING gist (location);

CREATE INDEX submissions_plant_id_idx ON public.submissions USING btree (plant_id);

CREATE INDEX submissions_status_idx ON public.submissions USING btree (status);

CREATE INDEX submissions_user_id_idx ON public.submissions USING btree (user_id);

CREATE TRIGGER plant_edits_set_updated_at
  BEFORE UPDATE ON public.plant_edits
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER plants_set_updated_at
  BEFORE UPDATE ON public.plants
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_at();

CREATE TRIGGER submissions_set_updated_at
  BEFORE UPDATE ON public.submissions
  FOR EACH ROW
  EXECUTE FUNCTION public.set_updated_at();

COMMENT ON EXTENSION "postgis" IS 'PostGIS geometry and geography spatial types and functions';

GRANT EXECUTE ON FUNCTION "public"."set_updated_at"() TO PUBLIC, "anon", "authenticated";

REVOKE ALL ON FUNCTION "public"."set_updated_at"() FROM "postgres";

GRANT EXECUTE ON FUNCTION "public"."set_updated_at"() TO "postgres";

GRANT EXECUTE ON FUNCTION "public"."set_updated_at"() TO "service_role";

